#include "dfre/mission_df_network_select.hpp"
#include <array>
#include <cstdlib>
#include <iostream>
#include <sstream>
#include <stdexcept>
namespace {using U=std::uint32_t;constexpr U sites[]={0x497370,0x4974a0,0x4b8f20,0x4b8f40};
struct Test{std::array<U,24>row{};std::vector<std::uint8_t>df=std::vector<std::uint8_t>(0xa00000),data=std::vector<std::uint8_t>(0x10000),stack=std::vector<std::uint8_t>(8);U reads=0,writes=0,calls=0;std::uint64_t trace=0;constexpr static U f=0x3000000;
std::uint8_t*ptr(U a,U n){if(a>=0x400000&&std::uint64_t(a-0x400000)+n<=df.size())return df.data()+a-0x400000;if(a>=0x1200000&&std::uint64_t(a-0x1200000)+n<=data.size())return data.data()+a-0x1200000;if(a>=f&&std::uint64_t(a-f)+n<=stack.size())return stack.data()+a-f;throw std::runtime_error("Selection address is not mapped");}U get(U a,U n=4){U v=0;for(U i=0;i<n;++i)v|=U(*ptr(a+i,1))<<(8*i);return v;}void put(U a,U v,U n=4){for(U i=0;i<n;++i)*ptr(a+i,1)=std::uint8_t(v>>(8*i));}U norm(U a){return a>=f&&a<f+8?0x30000000+a-f:a;}void event(U v){for(U i=0;i<4;++i){trace^=std::uint8_t(v>>(8*i));trace*=1099511628211ull;}}bool mapped(U a,U n){try{ptr(a,n);return true;}catch(...){return false;}}
void setup(){std::fill(df.begin(),df.end(),0x5a);std::fill(data.begin(),data.end(),0x5a);std::fill(stack.begin(),stack.end(),0x5a);reads=writes=calls=0;trace=1469598103934665603ull;put(0x501320,row[1]);put(0x501324,row[5]);put(0x501398,row[4]);put(0x50139c,row[3]);put(0x501ab8+0x1c,row[12]);put(0x501a28+0x1c,0x4b7810);put(0x1200000,0x1201000);put(f+4,row[0]==0?row[2]:row[11]==1?0:row[11]==2?f+4:0x1200000);}
dfre::MissionGameTransportBindings bindings(){dfre::MissionGameTransportBindings b;b.read=[&](U a,U n){if(std::getenv("DFRE_TRACE"))std::cerr<<"R "<<norm(a)<<" "<<n<<'\n';event(1);event(norm(a));event(n);if(++reads==row[8]||!mapped(a,n))throw std::runtime_error("Read failure");if((row[7]&32)&&a==0x50139c)put(0x501320,0);if((row[7]&64)&&a==0x501398)put(0x501ab8+0x1c,0x1100000);if((row[7]&128)&&a==0x501ab8+0x1c)put(0x501398,0x501a28);return get(a,n);};b.write=[&](U a,U n,U v){if(std::getenv("DFRE_TRACE"))std::cerr<<"W "<<norm(a)<<" "<<n<<" "<<norm(v)<<'\n';event(2);event(norm(a));event(n);event(norm(v));if(++writes==row[9]||!mapped(a,n))throw std::runtime_error("Write failure");put(a,v,n);};b.before_call=[&](U s,const auto&args){if(std::getenv("DFRE_TRACE")){std::cerr<<"C "<<s;for(U v:args)std::cerr<<" "<<norm(v);std::cerr<<'\n';}event(3);event(s);event(U(args.size()));for(U v:args)event(norm(v));if(++calls==row[10])throw std::runtime_error("Call failure");if(s==0x4974a0){if(row[7]&1){put(0x501398,0x501a28);put(0x50139c,0x501ab8);}if(row[7]&2)put(0x501320,0);}else if(s==0x4c5556){if(row[7]&8){put(0x501324,99);put(0x1200000,0x1202000);}}else if(s==0x4c5550){if(row[7]&16){put(0x501320,0);put(0x501324,99);}}else if(row[7]&4){put(0x501398,0x501a28);put(0x50139c,0x501a28);}};b.call=[&](U s,const auto&)->U{if(s==0x4b8ef0||s==0x4b7810||s==0x1100000||s==0x4c5556||s==0x4c5550)return row[6];throw std::runtime_error("Selection required service is not bound");};return b;}
};}
int main(){Test t;std::string line;while(std::getline(std::cin,line)){if(line.empty())continue;std::istringstream in(line);for(U&v:t.row)if(!(in>>v))return 2;t.setup();auto b=t.bindings();bool failed=false;U result=0;try{result=dfre::mission_df_network_select_call(b,sites[t.row[0]],t.f);}catch(const std::runtime_error&){failed=true;}if(failed||t.row[0]<2)result=0;std::uint64_t state=1469598103934665603ull;for(auto[a,n]:std::vector<std::pair<U,U>>{{0x501320,0x80},{0x501a28,0xc0},{0x1200000,0x3000}})for(U i=0;i<n;++i){state^=t.get(a+i,1);state*=1099511628211ull;}std::cout<<failed<<' '<<result<<' '<<t.reads<<' '<<t.writes<<' '<<t.calls<<' '<<t.trace<<' '<<state<<'\n';}}
